import gymimport jsonimport randomimport numpy as npimport pandas as pdfrom gym import spacesclass DataFrameEnv(gym.Env):    """DataFrame environment for OpenAI gym"""    metadata = {'render.modes': ['human']}    def __init__(self, df, model, features, control_variables, target, bounds):        super(DataFrameEnv, self).__init__()        # training data        self.df = df        # self.df drop target        self.df = self.df.drop(columns=[target])        # training model        self.model = model        # model features        self.features = features        # control variables in the model        self.control_variables = control_variables        # context variables        self.context_variables = list(set(self.features).difference(self.control_variables))        # bounds for each variable        self.bounds = bounds        # control target        self.target = target        # counter        self.counter = 0                # limits on action space        lower_lim = np.array(            self.bounds[bounds["variable"].isin(self.control_variables)]["lower_lim"])        upper_lim = np.array(            self.bounds[bounds["variable"].isin(self.control_variables)]["upper_lim"])        # set action space        self.action_space = spaces.Box(            low=np.ones(len(self.control_variables)) * lower_lim,            high=np.ones(len(self.control_variables)) * upper_lim,            dtype=np.float32)                # limits on observation space        lower_lim = np.array(            self.bounds[bounds["variable"].isin(self.features)]["lower_lim"])        upper_lim = np.array(            self.bounds[bounds["variable"].isin(self.features)]["upper_lim"])        # set observation space        self.observation_space = spaces.Box(            low=np.ones(len(self.features)) * lower_lim,            high=np.ones(len(self.features)) * upper_lim,            dtype=np.float32)        # max episodes        self._max_episode_steps = len(self.df)        # current state        self.current_step = 0        # initial uplift on the episode        self.uplift = 0        # mean uplift        self.cumulative_uplift = 0        # current observarions        self.observations = np.zeros(len(self.features))        # actual predictions        self.pred = 0        # take control in the action        self.pred_action = 0    # # TODO: vectorize this function    # def _penalize_reward(self, df_action):    #     cv_bounds = self.bounds[self.bounds["variable"].isin(self.control_variables)]    #     n_penalizations = 0    #     for control in self.control_variables:    #         lower_lim =  cv_bounds[cv_bounds["variable"] == control]["lower_lim"].values[0]    #         upper_lim =  cv_bounds[cv_bounds["variable"] == control]["upper_lim"].values[0]    #         variable = df_action[control].values[0]    #         if (variable < lower_lim) | (variable > upper_lim):    #             n_penalizations += 1    #     # negative penalization for every    #     global_penalization = - 1e2 * n_penalizations    #     return global_penalization            def _take_action(self, action):        # get the current state on the dataframe        df_frame = self.df.loc[self.current_step: self.current_step]        df_frame.reset_index(drop=True, inplace=True)        # action taked on the dataframe        action_array = np.array(list(action))        action_array = np.reshape(action_array, (-1, len(self.control_variables)))        df_action = pd.DataFrame(action_array, columns=self.control_variables)                # penalize the action taked if it is not on the limits        # global_penalization = _penalize_reward(df_action)        # dataframe where it is modified by the action        to_explore_df = df_frame.copy()        # model prediction with the actual step [REAL state]        self.pred = self.model.predict(df_frame[self.features])[0]        # modified actionable columns        for col in self.control_variables:            to_explore_df[col] = df_action[col]                 # model prediction with modified action [Posible state]        self.pred_action = self.model.predict(to_explore_df)[0]        # penalize        # TODO: vectorize this in a method        cv_bounds = self.bounds[self.bounds["variable"].isin(self.control_variables)]        n_penalizations = 0        for control in self.control_variables:            lower_lim =  cv_bounds[cv_bounds["variable"] == control]["lower_lim"].values[0]            upper_lim =  cv_bounds[cv_bounds["variable"] == control]["upper_lim"].values[0]            variable = df_action[control].values[0]            if (variable < lower_lim) | (variable > upper_lim):                n_penalizations += 1        # negative penalization for every        global_penalization = - 1e2 * n_penalizations        # compute reward        if global_penalization == 0:            # get the uplift obtain by the action taked            if self.current_step != 0:                self.uplift = (self.pred_action - self.pred) / self.pred * 100            else:                self.uplfit = 0            # cumulative uplift on the episode            self.cumulative_uplift = (                self.uplift + self.cumulative_uplift * self.counter) / (                    self.counter + 1)        else:            # get the uplift obtain by the action taked            self.uplift = global_penalization            # cumulative uplift on the episode            self.cumulative_uplift = (                self.uplift + self.cumulative_uplift * self.counter) / (                    self.counter + 1)                                            def _next_observation(self):        if self.current_step == len(self.df):            self.current_step = 0                df_frame = self.df.loc[self.current_step: self.current_step]         # get the dataframe array        frame = np.array(df_frame)        frame = np.reshape(frame, (-1, len(self.features)))        return frame                                                  def step(self, action):        # Execute one time step within the environment        self._take_action(action)        self.current_step += 1        # coutner + 1         self.counter += 1        # end when it pass the last dataframe        done = self.current_step == len(self.df)        # current step + 1        if self.current_step > len(self.df):            self.current_step = 0        # TODO: verify if it is better to use or not this delay        # delay_modifier = (self.current_step / MAX_STEPS)        reward = self.uplift              # get the new observation state        obs = self._next_observation()        # print("counter: ", self.counter)        # print("current_step:", self.current_step)        # print("uplift: ", self.uplift)        return obs, reward, done, {}    def reset(self):        # Reset the state of the environment to an initial state        # current state        self.current_step = 0        # initial uplift on the episode        self.uplift = 0        # mean uplift        self.cumulative_uplift = 0        # current observarions        self.observations = np.zeros(len(self.features))        # actual predictions        self.pred = 0        # take control in the action        self.pred_action = 0        return self._next_observation()    def render(self, mode='human', close=False):        # Render the environment to the screen        print(f'Step: {self.current_step}')        print(f'Uplift balance: {self.uplift} [%]')